<template>
  <div class="inem-notas p-2 p-md-3">
    <div class="mb-3">
      <b-button variant="outline-primary" @click="volverAlMenu">← Regresar al menú del estudiante</b-button>
    </div>

    <div v-if="cargando" class="text-center py-5">
      <b-spinner variant="primary" style="width:3rem;height:3rem;"></b-spinner>
      <p class="mt-3 text-muted">Cargando notas...</p>
    </div>

    <template v-else>
      <!-- Banner estudiante con identidad INEM -->
      <b-card class="mb-3 inem-banner shadow-sm border-0">
        <b-row class="align-items-center">
          <b-col cols="auto" class="text-center pr-3">
            <img v-if="estudiante.foto" :src="estudiante.foto" class="inem-foto" alt="foto">
            <div v-else class="inem-foto inem-foto-placeholder d-inline-flex align-items-center justify-content-center">
              <CIcon name="cil-user" height="34"/>
            </div>
          </b-col>
          <b-col>
            <h5 class="mb-1 text-uppercase">{{ estudiante.estudiante || '-' }}</h5>
            <div class="small" style="opacity:.75">{{ estudiante.tipodocumento }} {{ estudiante.documento }}</div>
            <div class="d-flex flex-wrap mt-2" style="gap:.4rem">
              <b-badge variant="light" class="text-dark">{{ estudiante.sede || '-' }}</b-badge>
              <b-badge variant="light" class="text-dark">{{ estudiante.grado || '-' }}</b-badge>
              <b-badge variant="warning"                    >{{ estudiante.curso || '-' }}</b-badge>
              <b-badge variant="light" class="text-dark"   >{{ vigencia }}</b-badge>
            </div>
          </b-col>
          <b-col cols="auto" class="text-right d-none d-md-block">
            <img src="escudo-tunja.png" alt="INEM" style="max-height:64px;" class="d-block mb-1">
            <small style="font-size:.65rem;opacity:.7;display:block;">IE INEM CARLOS ARTURO TORRES</small>
          </b-col>
        </b-row>
      </b-card>

      <!-- Leyenda criterios + conceptos -->
      <b-card class="mb-3 shadow-sm border-0" v-if="config">
        <b-row class="align-items-center">
          <b-col>
            <span class="font-weight-bold text-muted small mr-2">CRITERIOS:</span>
            <b-badge v-if="config.estadoC1" variant="primary"   class="mr-1 py-1 px-2">{{ config.nombreC1 }} {{ config.porcentajeC1 }}%</b-badge>
            <b-badge v-if="config.estadoC2" variant="info"      class="mr-1 py-1 px-2">{{ config.nombreC2 }} {{ config.porcentajeC2 }}%</b-badge>
            <b-badge v-if="config.estadoC3" variant="secondary" class="mr-1 py-1 px-2">{{ config.nombreC3 }} {{ config.porcentajeC3 }}%</b-badge>
          </b-col>
          <b-col cols="auto">
            <span class="conc-tag conc-bajo mr-1">BAJO</span>
            <span class="conc-tag conc-basico mr-1">BÁSICO</span>
            <span class="conc-tag conc-alto mr-1">ALTO</span>
            <span class="conc-tag conc-superior">SUPERIOR</span>
          </b-col>
        </b-row>
      </b-card>

      <!-- Selector de periodo -->
      <b-card class="mb-3 shadow-sm border-0">
        <b-row class="align-items-center">
          <b-col cols="auto"><span class="font-weight-bold text-muted small">PERIODO:</span></b-col>
          <b-col>
            <b-button-group size="sm">
              <b-button
                v-for="p in periodosDisponibles" :key="p"
                :variant="periodoSeleccionado === p ? 'primary' : 'outline-primary'"
                @click="periodoSeleccionado = p"
              >{{ p }}</b-button>
              <b-button
                :variant="periodoSeleccionado === null ? 'primary' : 'outline-primary'"
                @click="periodoSeleccionado = null"
              >Todos</b-button>
            </b-button-group>
          </b-col>
          <b-col cols="auto" class="text-muted small">{{ rowsFiltrados.length }} asignatura(s)</b-col>
        </b-row>
      </b-card>

      <!-- Sin notas -->
      <b-alert v-if="!rows.length && consultaRealizada" variant="warning" show class="mb-3">
        No se encontraron notas registradas para este estudiante en la vigencia {{ vigencia }}.
      </b-alert>

      <!-- Notas agrupadas por área -->
      <div v-for="(items, area) in porArea" :key="area" class="mb-4">
        <div class="area-header">{{ area }}</div>
        <b-card
          v-for="row in items" :key="row.__key"
          class="mb-2 shadow-sm border-0 asig-card"
          body-class="py-2 px-3"
        >
          <b-row class="align-items-center">
            <b-col cols="12" md="3" class="mb-2 mb-md-0">
              <div class="asig-nombre">{{ row.nombreAsignatura || row.nemo || '-' }}</div>
              <div class="text-muted" style="font-size:.73rem;">Periodo {{ row.periodo }}</div>
            </b-col>
            <b-col cols="12" md="9">
              <div class="criterios-inline">
                <div v-if="config && config.estadoC1" class="crit-box">
                  <div class="crit-label">{{ config.nombreC1 }}</div>
                  <div :class="['crit-val', scoreClass(row.defC1)]">{{ asScore(row.defC1) }}</div>
                </div>
                <div v-if="config && config.estadoC2" class="crit-box">
                  <div class="crit-label">{{ config.nombreC2 }}</div>
                  <div :class="['crit-val', scoreClass(row.defC2)]">{{ asScore(row.defC2) }}</div>
                </div>
                <div v-if="config && config.estadoC3" class="crit-box">
                  <div class="crit-label">{{ config.nombreC3 }}</div>
                  <div :class="['crit-val', scoreClass(row.defC3)]">{{ asScore(row.defC3) }}</div>
                </div>
                <div class="crit-box crit-definitiva">
                  <div class="crit-label">Definitiva</div>
                  <div :class="['crit-val', 'crit-val-lg', scoreClass(row.definitiva)]">{{ asScore(row.definitiva) }}</div>
                </div>
                <div class="crit-box">
                  <div class="crit-label">Concepto</div>
                  <div :class="['conc-tag', conceptoClass(row.concepto)]">{{ row.concepto || '—' }}</div>
                </div>
                <div v-if="Number(row.definitivacompor) > 0" class="crit-box">
                  <div class="crit-label">Compor.</div>
                  <div :class="['crit-val', scoreClass(row.definitivacompor)]">{{ asScore(row.definitivacompor) }}</div>
                </div>
                <div v-if="row.ausJ > 0 || row.ausS > 0" class="crit-box">
                  <div class="crit-label">Ausencias</div>
                  <div>
                    <span v-if="row.ausJ > 0" class="aus-badge mr-1">J:{{ row.ausJ }}</span>
                    <span v-if="row.ausS > 0" class="aus-badge aus-s">S:{{ row.ausS }}</span>
                  </div>
                </div>
              </div>
            </b-col>
          </b-row>
        </b-card>
      </div>
    </template>
  </div>
</template>

<script>
import axios from 'axios'
import * as CONFIG from '@/assets/config.js'

const ID_INEM = 'eb58bf60-fc83-11ec-a1d1-1dc2835404e5'

export default {
  name: 'ConsultaNotasInem',
  data () {
    return {
      cargando: false,
      consultaRealizada: false,
      rows: [],
      estudiante: {},
      vigencia: '',
      config: null,
      periodoSeleccionado: null
    }
  },
  computed: {
    periodosDisponibles () {
      return [...new Set(this.rows.map(r => r.periodo))].sort((a, b) => a - b)
    },
    rowsFiltrados () {
      if (this.periodoSeleccionado === null) return this.rows
      return this.rows.filter(r => r.periodo === this.periodoSeleccionado)
    },
    porArea () {
      const grupos = {}
      this.rowsFiltrados.forEach(r => {
        const area = r.nombreArea || r.nemoArea || 'Sin área'
        if (!grupos[area]) grupos[area] = []
        grupos[area].push(r)
      })
      return grupos
    }
  },
  methods: {
    volverAlMenu () {
      const idMatricula = this.$route.params.idMatricula
      this.$router.push({ name: 'menu-estudiante', params: { idMatricula: String(idMatricula || '') } })
    },
    asScore (v) {
      if (v === null || v === undefined || v === '' || v === 0 || v === '0') return '-'
      const n = Number(v)
      return Number.isNaN(n) ? String(v) : n.toFixed(1)
    },
    scoreClass (v) {
      const n = Number(v)
      if (!v || Number.isNaN(n) || n === 0) return 'score-none'
      if (n < 3.0) return 'score-bajo'
      if (n < 4.0) return 'score-basico'
      if (n < 4.5) return 'score-alto'
      return 'score-superior'
    },
    conceptoClass (concepto) {
      if (!concepto) return ''
      const c = String(concepto).toUpperCase().trim()
      if (c === 'SUPERIOR') return 'conc-superior'
      if (c === 'ALTO') return 'conc-alto'
      if (c === 'BASICO' || c === 'BÁSICO') return 'conc-basico'
      if (c === 'BAJO') return 'conc-bajo'
      return ''
    },
    mensajeEmergente (variante, titulo, contenido) {
      this.$bvToast.toast(contenido, { title: titulo, variant: variante, toaster: 'b-toaster-top-center', solid: true, autoHideDelay: 3500, appendToast: false })
    },
    async cargarConfig () {
      try {
        const resp = await axios.get(CONFIG.ROOT_PATH + 'acudientes/config-evaluacion', {
          params: { idInstitucion: ID_INEM, vigencia: this.vigencia }
        })
        if (!resp.data.error && resp.data.datos) this.config = resp.data.datos
      } catch (e) { /* config no crítico */ }
    },
    async cargarNotas () {
      const idMatricula = this.$route.params.idMatricula
      if (!idMatricula) return
      this.cargando = true
      this.rows = []
      try {
        const resp = await axios.get(CONFIG.ROOT_PATH + 'acudientes/historico-notas/estudiante', {
          params: { idMatricula, periodo: 5, vigencia: this.vigencia },
          timeout: 20000
        })
        if (!resp.data.error && resp.data.datos !== 0) {
          this.rows = (resp.data.datos || []).map((r, idx) => ({
            __key: `${r.idAsignaturaCurso || idx}-${r.periodo}`,
            periodo: r.periodo,
            nemoArea: r.nemoArea || '',
            nombreArea: r.nombreArea || '',
            nemo: r.nemo || '',
            nombreAsignatura: r.nombreAsignatura || '',
            defC1: r.defC1,
            defC2: r.defC2,
            defC3: r.defC3,
            definitiva: r.definitiva,
            recuperacion: r.recuperacion,
            definitivacompor: r.definitivacompor,
            definitivapree: r.definitivapree,
            concepto: r.concepto,
            ausJ: Number(r.ausJ) || 0,
            ausS: Number(r.ausS) || 0,
            observaciones: r.observaciones || '',
            tipoAsignatura: r.tipoAsignatura || 1
          }))
          // Seleccionar automáticamente el último periodo con datos
          if (this.periodosDisponibles.length) {
            this.periodoSeleccionado = this.periodosDisponibles[this.periodosDisponibles.length - 1]
          }
        }
      } catch (e) {
        this.mensajeEmergente('danger', CONFIG.TITULO_MSG, 'Error cargando las notas. ' + e)
      } finally {
        this.cargando = false
        this.consultaRealizada = true
      }
    }
  },
  beforeMount () {
    const idMatricula = this.$route.params.idMatricula
    if (!idMatricula) {
      this.$router.replace({ name: 'inicio-acudiente' })
      return
    }
    const estudiantes = JSON.parse(sessionStorage.getItem('acudienteEstudiantes') || '[]')
    this.estudiante = estudiantes.find(x => String(x.idMatricula) === String(idMatricula)) || {}
    this.vigencia = sessionStorage.getItem('acudienteVigencia') || String(new Date().getFullYear())
    this.cargarConfig()
    this.cargarNotas()
  }
}
</script>

<style scoped>
