.conc-basico      { background: rgba(210,155,10,.2);   color: #896008; }
.conc-alto        { background: rgba(20,90,200,.15);   color: #1452a5; }
.conc-superior    { background: rgba(22,140,70,.18);   color: #0f6b30; }

/* Área header */
.area-header {
  background: #dce6f5; color: #1a3f7a; font-weight: 700; font-size: .83rem;
