}

/* Asignatura card */
.asig-card { border-left: 3px solid #0050b3 !important; }
.asig-nombre { font-weight: 600; font-size: .92rem; color: #1a3058; }

/* Criterios inline */
.criterios-inline { display: flex; flex-wrap: wrap; gap: .65rem; align-items: flex-end; }
.crit-box         { text-align: center; }
.crit-label       { font-size: .66rem; color: #7b8ea6; text-transform: uppercase; letter-spacing: .03em; margin-bottom: 2px; }
.crit-val         { font-weight: 700; font-size: .95rem; padding: .1rem .45rem; border-radius: 6px; min-width: 42px; display: inline-block; }
.crit-val-lg      { font-size: 1.1rem; min-width: 48px; }
.crit-definitiva .crit-val { font-size: 1.2rem; }

/* Score colors */
.score-none    { background: #eceff4; color: #99a5b3; }
.score-bajo    { background: rgba(200,40,40,.14);  color: #a82828; }
.score-basico  { background: rgba(210,155,10,.18); color: #896008; }
.score-alto    { background: rgba(20,90,200,.15);  color: #1452a5; }
.score-superior{ background: rgba(22,140,70,.18);  color: #0f6b30; }

/* Ausencias */
.aus-badge     { font-size: .72rem; font-weight: 700; padding: .1rem .32rem; border-radius: 4px; background: rgba(200,40,40,.14); color: #a82828; }
.aus-badge.aus-s { background: rgba(210,155,10,.18); color: #896008; }
</style>

      <b-col lg="12">
        <b-card>
          <template #header>
            <h5 class="mb-0">
              <b-icon icon="card-checklist" aria-hidden="true"></b-icon>
              CONSULTA DE NOTAS — INEM CARLOS ARTURO TORRES
            </h5>
          </template>
          <b-card-text>

            <!-- Filtros -->
            <b-row>
              <b-col lg="2">
                <b-form-group label="Vigencia:" label-for="vigencia" class="etiqueta">
                  <b-form-input
                    id="vigencia"
                    v-model.number="vigencia"
                    type="number"
                    min="2020"
                    max="2099"
                    @change="resetFiltros"
                  ></b-form-input>
                </b-form-group>
              </b-col>

              <b-col lg="3">
                <b-form-group label="Sede:" label-for="sede" class="etiqueta">
                  <b-form-select
                    id="sede"
                    v-model="idSedeSeleccionada"
                    :options="comboSedes"
                    :disabled="comboSedes.length === 0"
                    @change="idCursoSeleccionado = null"
                  >
                    <template #first>
                      <b-form-select-option :value="null">-- Seleccione sede --</b-form-select-option>
                    </template>
                  </b-form-select>
                </b-form-group>
              </b-col>

              <b-col lg="3">
                <b-form-group label="Curso:" label-for="curso" class="etiqueta">
                  <b-form-select
                    id="curso"
                    v-model="idCursoSeleccionado"
                    :options="comboCursosFiltrados"
                    :disabled="idSedeSeleccionada == null"
                  >
                    <template #first>
                      <b-form-select-option :value="null">-- Seleccione curso --</b-form-select-option>
                    </template>
                  </b-form-select>
                </b-form-group>
              </b-col>

              <b-col lg="2">
                <b-form-group label="Periodo:" label-for="periodo" class="etiqueta">
                  <b-form-select
                    id="periodo"
                    v-model="periodoSeleccionado"
                    :options="comboPeriodos"
                    :disabled="idCursoSeleccionado == null"
                  ></b-form-select>
                </b-form-group>
              </b-col>

              <b-col lg="2" class="d-flex align-items-end pb-3">
                <b-button
                  variant="primary"
                  :disabled="idCursoSeleccionado == null || cargando"
                  @click="consultarNotas"
                  block
                >
                  <b-spinner v-if="cargando" small></b-spinner>
                  <span v-else><b-icon icon="search"></b-icon> Consultar</span>
                </b-button>
              </b-col>
            </b-row>

            <!-- Info del curso seleccionado -->
            <b-row v-if="infoCurso" class="mb-2">
              <b-col>
                <b-badge variant="info"      class="mr-2">{{ infoCurso.sede }}</b-badge>
                <b-badge variant="secondary" class="mr-2">{{ infoCurso.grado }}</b-badge>
                <b-badge variant="dark">{{ infoCurso.curso }}</b-badge>
              </b-col>
            </b-row>

            <b-row><b-col><hr class="mt-0"></b-col></b-row>

            <!-- Estado inicial -->
            <b-row v-if="!consultaRealizada && !cargando">
              <b-col class="text-center text-muted py-4">
                <b-icon icon="info-circle" font-scale="2"></b-icon>
                <p class="mt-2">Seleccione sede, curso y periodo para consultar las notas.</p>
              </b-col>
            </b-row>

            <!-- Sin resultados -->
            <b-row v-if="consultaRealizada && notasFiltradas.length === 0 && !cargando">
              <b-col>
                <b-alert variant="warning" show>
                  No se encontraron notas registradas para el curso y periodo seleccionado.
                </b-alert>
              </b-col>
            </b-row>

            <!-- Tabla de resultados -->
            <div v-if="consultaRealizada && notasFiltradas.length > 0">
              <b-row class="mb-2">
                <b-col lg="4">
                  <b-form-input
                    v-model="filtroEstudiante"
                    placeholder="Filtrar por estudiante..."
                    size="sm"
                  ></b-form-input>
                </b-col>
                <b-col class="text-right">
                  <small class="text-muted">
                    {{ notasFiltradas.length }} registro(s) ·
                    {{ resumenEstudiantes }} estudiante(s)
                  </small>
                </b-col>
              </b-row>

              <vue-good-table
                :columns="columnas"
                :rows="notasFiltradas"
                styleClass="vgt-table condensed bordered striped"
                :line-numbers="true"
                :search-options="{ enabled: false }"
                :pagination-options="{ enabled: true, mode: 'pages', perPage: 50, perPageDropdown: [25, 50, 100, 200] }"
              >
                <template slot="table-row" slot-scope="props">
                  <span v-if="props.column.field === 'definitiva'">
                    <b-badge :variant="varianteNota(props.row.definitiva)" style="font-size:0.9em;">
                      {{ props.row.definitiva | formatoNota }}
                    </b-badge>
                  </span>
                  <span v-else-if="props.column.field === 'recuperacion'">
                    <span v-if="props.row.recuperacion > 0">
                      <b-badge variant="warning" style="font-size:0.9em;">
                        {{ props.row.recuperacion | formatoNota }}
                      </b-badge>
                    </span>
                    <span v-else class="text-muted">—</span>
                  </span>
                  <span v-else-if="props.column.field === 'ausencias'">
                    <span v-if="props.row.ausJ > 0 || props.row.ausS > 0">
                      <b-badge v-if="props.row.ausJ > 0" variant="danger"  class="mr-1">J:{{ props.row.ausJ }}</b-badge>
                      <b-badge v-if="props.row.ausS > 0" variant="warning">S:{{ props.row.ausS }}</b-badge>
                    </span>
                    <span v-else class="text-muted">—</span>
                  </span>
                  <span v-else-if="props.column.field === 'concepto'">
                    <span :class="claseConcepto(props.row.concepto)">{{ props.row.concepto || '—' }}</span>
                  </span>
                  <span v-else>{{ props.formattedRow[props.column.field] }}</span>
                </template>
                <div slot="emptystate">
                  <h6 class="text-danger ml-3">No hay registros para mostrar.</h6>
                </div>
              </vue-good-table>
            </div>

          </b-card-text>
          <template #footer>
            <em>Consulta de calificaciones — INEM Carlos Arturo Torres · Vigencia {{ vigencia }}</em>
          </template>
        </b-card>
      </b-col>
    </b-row>
  </div>
</template>

<script>
import axios from 'axios'
import * as CONFIG from '@/assets/config.js'
import 'vue-good-table/dist/vue-good-table.css'
import { VueGoodTable } from 'vue-good-table'

const PERIODOS_OPCIONES = [
  { value: 1, text: 'Periodo 1' },
  { value: 2, text: 'Periodo 2' },
  { value: 3, text: 'Periodo 3' },
  { value: 4, text: 'Periodo 4' },
]

export default {
  name: 'consultanotasinem',
  components: { VueGoodTable },
  filters: {
    formatoNota(val) {
      if (val === null || val === undefined) return '—'
      const n = parseFloat(val)
      return isNaN(n) ? val : n.toFixed(1)
    }
  },
  data() {
    return {
      vigencia: new Date().getFullYear(),
      idSedeSeleccionada: null,
      idCursoSeleccionado: null,
      periodoSeleccionado: 1,
      comboPeriodos: PERIODOS_OPCIONES,
      listaCursos: [],
      comboSedes: [],
      notasRaw: [],
      cargando: false,
      consultaRealizada: false,
      filtroEstudiante: '',
    }
  },
  computed: {
    comboCursosFiltrados() {
      if (!this.idSedeSeleccionada) return []
      return this.listaCursos
        .filter(c => c.idSede === this.idSedeSeleccionada)
        .map(c => ({ value: c.idCurso, text: c.curso.toUpperCase() }))
    },
    infoCurso() {
      if (!this.idCursoSeleccionado) return null
      return this.listaCursos.find(c => c.idCurso === this.idCursoSeleccionado) || null
    },
    notasFiltradas() {
      if (!this.filtroEstudiante.trim()) return this.notasRaw
      const buscar = this.filtroEstudiante.trim().toLowerCase()
      return this.notasRaw.filter(r => r.estudiante.toLowerCase().includes(buscar))
    },
    resumenEstudiantes() {
      return new Set(this.notasFiltradas.map(r => r.idMatricula)).size
    },
    columnas() {
      return [
        { label: 'Estudiante', field: 'estudiante',  sortable: true,  thClass: 'text-center', tdClass: 'text-left' },
        { label: 'Área',       field: 'area',        sortable: true,  thClass: 'text-center', tdClass: 'text-left' },
        { label: 'Asignatura', field: 'asignatura',  sortable: true,  thClass: 'text-center', tdClass: 'text-left' },
        { label: 'Definitiva', field: 'definitiva',  sortable: true,  thClass: 'text-center', tdClass: 'text-center', width: '95px',  type: 'number' },
        { label: 'Recupera',   field: 'recuperacion',sortable: true,  thClass: 'text-center', tdClass: 'text-center', width: '90px',  type: 'number' },
        { label: 'Concepto',   field: 'concepto',    sortable: true,  thClass: 'text-center', tdClass: 'text-center', width: '90px'  },
        { label: 'Ausencias',  field: 'ausencias',   sortable: false, thClass: 'text-center', tdClass: 'text-center', width: '110px' },
      ]
    },
  },
  methods: {
    resetFiltros() {
      this.idSedeSeleccionada = null
      this.idCursoSeleccionado = null
      this.notasRaw = []
      this.consultaRealizada = false
      this.cargarCursos()
    },
    async cargarCursos() {
      this.listaCursos = []
      this.comboSedes = []
      try {
        const resp = await axios.get(CONFIG.ROOT_PATH + 'acudientes/notas-inem/cursos', {
          params: { vigencia: this.vigencia }
        })
        if (resp.data.error || resp.data.datos === 0) return
        this.listaCursos = resp.data.datos
        const sedesVistas = new Set()
        resp.data.datos.forEach(c => {
          if (!sedesVistas.has(c.idSede)) {
            sedesVistas.add(c.idSede)
            this.comboSedes.push({ value: c.idSede, text: c.sede.toUpperCase() })
          }
        })
      } catch (err) {
        this.mensajeEmergente('danger', CONFIG.TITULO_MSG, 'Error cargando cursos INEM. ' + err)
      }
    },
    async consultarNotas() {
      this.cargando = true
      this.notasRaw = []
      this.consultaRealizada = false
      this.filtroEstudiante = ''
      try {
        const resp = await axios.get(CONFIG.ROOT_PATH + 'acudientes/notas-inem/consulta', {
          params: {
            idCurso: this.idCursoSeleccionado,
            periodo: this.periodoSeleccionado,
            vigencia: this.vigencia,
          }
        })
        if (resp.data.error) {
          this.mensajeEmergente('danger', CONFIG.TITULO_MSG, resp.data.mensaje)
        } else if (resp.data.datos !== 0) {
          this.notasRaw = resp.data.datos
        }
      } catch (err) {
        this.mensajeEmergente('danger', CONFIG.TITULO_MSG, 'Error consultando notas INEM. ' + err)
      } finally {
        this.cargando = false
        this.consultaRealizada = true
      }
    },
    varianteNota(val) {
      const n = parseFloat(val)
      if (isNaN(n)) return 'secondary'
      if (n >= 6.0) return 'success'
      if (n >= 3.0) return 'warning'
      return 'danger'
    },
    claseConcepto(concepto) {
      if (!concepto) return 'text-muted'
      const c = concepto.trim().toUpperCase()
      if (c === 'S' || c === 'A') return 'font-weight-bold text-success'
      if (c === 'B') return 'font-weight-bold text-primary'
      if (c === 'D') return 'font-weight-bold text-danger'
      return ''
    },
    mensajeEmergente(variante, titulo, contenido) {
      this.$bvToast.toast(contenido, {
        title: titulo, variant: variante,
        toaster: 'b-toaster-top-center', solid: true,
        autoHideDelay: 4000, appendToast: false
      })
    },
  },
  mounted() {
    this.cargarCursos()
  },
}
</script>
